from collections import Counter, defaultdict
from typing import List

MOD = 10**9 + 7


def _parity_ways(k: int):
    """k 个相同元素各自 白/黑/不涂，按 (白色个数奇偶, 黑色个数奇偶) 分类的方案数。"""
    # N(pw,pb) = 1/4 * sum_{s,t in ±1} s^pw t^pb (1+s+t)^k
    res = {}
    for pw in (0, 1):
        for pb in (0, 1):
            tot = 0
            for s in (1, -1):
                for t in (1, -1):
                    tot += (s ** pw) * (t ** pb) * (1 + s + t) ** k
            res[(pw, pb)] = tot // 4
    return res


def xorColoring(A: List[int]) -> int:
    # ponytail: 状态是可达的 (x, y) 对，数量最多 4^rank；rank 小时很快，满约束（rank 到 17）会爆，需要原题的进一步条件
    dp = {(0, 0): 1}
    for a, k in Counter(A).items():
        ways = {key: v % MOD for key, v in _parity_ways(k).items()}
        nxt = defaultdict(int)
        for (x, y), c in dp.items():
            for (pw, pb), w in ways.items():
                if w:
                    key = (x ^ (a if pw else 0), y ^ (a if pb else 0))
                    nxt[key] = (nxt[key] + c * w) % MOD
        dp = nxt
    ans = 0
    for (x, y), c in dp.items():
        if x > 0 and y > 0 and (x % y == 0 or y % x == 0):
            ans += c
    return ans % MOD


def _brute(A):
    from itertools import product
    cnt = 0
    for col in product(range(3), repeat=len(A)):
        x = y = 0
        for a, c in zip(A, col):
            if c == 1:
                x ^= a
            elif c == 2:
                y ^= a
        if x > 0 and y > 0 and (x % y == 0 or y % x == 0):
            cnt += 1
    return cnt


if __name__ == "__main__":
    import random
    assert xorColoring([1, 1]) == 2  # 一白一黑，x=y=1
    for _ in range(200):
        A = [random.randint(1, 12) for _ in range(random.randint(1, 7))]
        assert xorColoring(A) == _brute(A), A
    print("ok")
